scwin.doSave = async function () {
    /* sdd-asis-lifecycle:begin doSave — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    form.action = '/listInvstg/listFee.do';
    let msg = '저장하시겠습니까?';
    if (loadTp === '2' || loadTp === '3') {
        msg = '수정하시겠습니까?';
        $c.util.getComponent('dma_doSaveReq').set('method', 'editFeeInfo');
    } else {
        $c.util.getComponent('dma_doSaveReq').set('method', 'saveFeeInfo');
    }
    if (await scwin.checkValue()) {
        if (await $c.win.confirm(msg)) {
            $c.util.getComponent('rd_listFeeAnulfeeTpCd').setItemDisabled(0, !!(false));
            $c.util.getComponent('rd_listFeeAnulfeeTpCd').setItemDisabled(1, !!(false));
            await scwin.tx_doSave();
        }
    }
    /* sdd-asis-lifecycle:end */
};


