scwin.openComInfo4fee = async function () {
    /* sdd-asis-lifecycle:begin openComInfo4fee — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const obj = $c.util.getComponent('rd_listFeeAnulfeeTpCd');
    let feeTp = '';
